#include "cf_board_config.h"
#include <stdio.h>
#define R(a) (*(volatile unsigned*)(a))
volatile unsigned width,have_rise,measured;
void TIM2_IRQHandler(void){
  if(R(0x40000010)&2u){
    unsigned value=R(0x40000034);
    if(cf_gpio_read(PA0))have_rise=1;
    else if(have_rise){width=value;measured++;}
  }
}
int main(void){
  // PA1 PWM and PA0 input capture share TIM2; main sets their timebase.
  cf_pwm_begin(PA1,1000,50);
  R(0x40000018)=(R(0x40000018)&~255u)|1u;
  R(0x40000020)=(R(0x40000020)&~15u)|11u;
  R(0x4000000c)=2u;
  R(0xe000e100)=1u<<28;
  puts("CAPTURE STATION READY");
  for(;;){
    int adc=cf_adc_read(PB1);
    unsigned requested=(adc*100u+2047u)/4095u;
    cf_pwm_duty(PA1,requested);
    while(!measured)__asm volatile("wfi");
    unsigned period=R(0x4000002c)+1u,scale=R(0x40000028)+1u;
    unsigned pulse=width,pct=(pulse*100u+period/2u)/period;
    printf("REQ=%u MEAS=%u WIDTH=%u us PERIOD=%u us ADC=%d\r\n",
      requested,pct,pulse*scale/(CF_CPU_HZ/1000000u),period*scale/(CF_CPU_HZ/1000000u),adc);
    cf_delay_ms(20);
  }
}

